$GLOBALS['posts']=array();$GLOBALS['meta']=array();$GLOBALS['transients']=array();$GLOBALS['next_id']=1;$GLOBALS['assertions']=0;$GLOBALS['failures']=0;
class WP_Error{private $code,$message;public function __construct($c,$m){$this->code=$c;$this->message=$m;}public function get_error_code(){return $this->code;}public function get_error_message(){return $this->message;}}
function is_wp_error($v){return $v instanceof WP_Error;}function add_action(){return true;}function register_post_type(){return true;}function post_type_exists(){return true;}function get_current_user_id(){return 7;}function current_user_can($cap){return $cap==='manage_options'||strpos($cap,'design_core_')===0;}function sanitize_key($v){return strtolower(preg_replace('/[^a-z0-9_\-]/','',(string)$v));}function sanitize_text_field($v){return trim(strip_tags((string)$v));}function wp_json_encode($v,$flags=0){return json_encode($v,$flags);}function wp_generate_uuid4(){return '11111111-2222-4333-8444-555555555555';}
function wp_insert_post($data,$wp_error=false){$id=$GLOBALS['next_id']++;$GLOBALS['posts'][$id]=(object)array('ID'=>$id,'post_title'=>$data['post_title'],'post_author'=>$data['post_author'],'post_type'=>$data['post_type'],'post_status'=>$data['post_status'],'post_date_gmt'=>gmdate('Y-m-d H:i:s'));return $id;}function wp_update_post($data,$wp_error=false){$id=(int)$data['ID'];if(!isset($GLOBALS['posts'][$id]))return new WP_Error('missing','missing');foreach($data as $k=>$v){if($k!=='ID')$GLOBALS['posts'][$id]->$k=$v;}return $id;}
function update_post_meta($id,$key,$value){$GLOBALS['meta'][$id][$key]=array($value);return true;}function add_post_meta($id,$key,$value,$unique=false){$GLOBALS['meta'][$id][$key][]=$value;return true;}function get_post_meta($id,$key='',$single=false){if($key==='')return $GLOBALS['meta'][$id]??array();$vals=$GLOBALS['meta'][$id][$key]??array();return $single?($vals[0]??''):$vals;}
function get_posts($args){$out=array_values($GLOBALS['posts']);if(isset($args['post_type']))$out=array_values(array_filter($out,fn($p)=>$p->post_type===$args['post_type']));if(isset($args['author']))$out=array_values(array_filter($out,fn($p)=>(int)$p->post_author===(int)$args['author']));if(isset($args['meta_key'])){$key=$args['meta_key'];$val=$args['meta_value']??null;$out=array_values(array_filter($out,function($p)use($key,$val){$got=get_post_meta($p->ID,$key,true);return null===$val?(bool)$got:(string)$got===(string)$val;}));}usort($out,fn($a,$b)=>$b->ID<=>$a->ID);$offset=(int)($args['offset']??0);$limit=(int)($args['posts_per_page']??count($out));return array_slice($out,$offset,$limit);}
function set_transient($k,$v,$ttl=0){$GLOBALS['transients'][$k]=$v;return true;}function get_transient($k){return $GLOBALS['transients'][$k]??false;}function delete_transient($k){unset($GLOBALS['transients'][$k]);return true;}
function dc_assert($cond,$msg){$GLOBALS['assertions']++;if(!$cond){$GLOBALS['failures']++;fwrite(STDERR,"FAIL: $msg\n");}}
