$start=Design_Core_Elementor_Design_Run_Trace::start(array('task'=>'Dimension rebuild','page_id'=>81,'source_hash'=>$source,'client'=>'chatgpt-web'));dc_assert(!is_wp_error($start),'run starts');$run=$start['run']['run_id'];dc_assert($run===Design_Core_Elementor_Design_Run_Trace::active_run_id(),'run becomes active');dc_assert($start['run']['event_count']===1,'start event recorded');
$secret=Design_Core_Elementor_Design_Run_Trace::append_event($run,array('event_type'=>'decision','phase'=>'widget_selection','status'=>'pass','summary'=>'Choose steps','component_id'=>'process-1','decision'=>array('selected_widget'=>'dc-steps','authorization'=>'Bearer secret','nested'=>array('api_key'=>'abc')),'artifact_hash'=>$hashA));dc_assert($secret['event']['decision']['authorization']==='[redacted]','authorization redacted');dc_assert($secret['event']['decision']['nested']['api_key']==='[redacted]','api key redacted');
foreach(array('semantic_qa'=>'semantic_planning','structural_qa'=>'compile','visual_qa'=>'visual_qa','interaction_qa'=>'interaction_qa') as $qa=>$phase){Design_Core_Elementor_Design_Run_Trace::append_event($run,array('event_type'=>'qa','phase'=>$phase,'status'=>'pass','summary'=>$qa.' pass','artifact_hash'=>$hashA,'metadata'=>array($qa=>'pass','schema_validation'=>$qa==='structural_qa'?'pass':'')));}
$get=Design_Core_Elementor_Design_Run_Trace::get($run);dc_assert($get['run']['summary']['promotion_ready']===true,'promotion readiness derives from same artifact evidence');dc_assert($get['run']['summary']['qa']['visual']==='pass','visual pass captured');
Design_Core_Elementor_Design_Run_Trace::append_event($run,array('event_type'=>'correction','phase'=>'correction','status'=>'pass','summary'=>'Changed controls','artifact_hash'=>$hashB));$stale=Design_Core_Elementor_Design_Run_Trace::get($run);dc_assert($stale['run']['summary']['qa']['visual']==='stale','visual QA becomes stale after artifact changes');dc_assert($stale['run']['summary']['promotion_ready']===false,'stale evidence locks promotion readiness');
$result=Design_Core_Elementor_Design_Run_Trace::around('mcp','agent-semantic-component-plan',array('component_type'=>'process-steps','api_key'=>'should-never-store'),function()use($hashB){return array('status'=>'ok','artifact_hash'=>$hashB,'recommendation'=>array('type'=>'direct_widget','widget'=>'dc-steps','score'=>.97,'reason'=>'fit'),'decision_hash'=>str_repeat('d',64));});dc_assert($result['status']==='ok','around preserves result');$events=Design_Core_Elementor_Design_Run_Trace::events($run,array('limit'=>100));$last=end($events['events']);dc_assert($last['operation']==='agent-semantic-component-plan','automatic operation traced');dc_assert(($last['metadata']['selected_widget']??'')==='dc-steps','selected widget summarized');$json=json_encode($events);dc_assert(strpos($json,'should-never-store')===false,'automatic trace never stores input secret');
$components=Design_Core_Elementor_Design_Run_Trace::components($run);dc_assert($components['count']>=1,'component summary produced');$artifacts=Design_Core_Elementor_Design_Run_Trace::artifacts($run);dc_assert(count($artifacts['artifacts'])===2,'artifact history keeps both revisions');
$integrity=Design_Core_Elementor_Design_Run_Trace::get($run);dc_assert($integrity['run']['summary']['integrity']['status']==='pass','event hash chain verifies');
Design_Core_Elementor_Design_Run_Trace::capture_change_ledger_update('design_core_elementor_change_ledger',array(),array(array('id'=>'dc-history-1','action'=>'elementor-save','object_type'=>'post','object_id'=>81,'before_hash'=>str_repeat('1',64),'after_hash'=>str_repeat('2',64),'rollback_of'=>'')));$afterLedger=Design_Core_Elementor_Design_Run_Trace::events($run,array('limit'=>100));$ledgerLast=end($afterLedger['events']);dc_assert(($ledgerLast['metadata']['history_entry_id']??'')==='dc-history-1','Change Ledger mutation links into active run');
